// src/context/useReactContext.tsx
import { createContext, useContext } from "react";

import { AppContextValueType } from "./AppContext";

export const AppContext = createContext<AppContextValueType | null>(null);

export const useAppContext = (): AppContextValueType => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useAppContext must be used within a AppContextProvider');
  }
  return context;
};

// src/context/AppContext.tsx
import { Dispatch, ReactNode, SetStateAction, useMemo, useState } from 'react';

import { AppContext } from './useReactContext';

export interface AppContextValueType {
  isGameActive: boolean;
  setIsGameActive: Dispatch<SetStateAction<boolean>>;
}

export const AppContextProvider = ({ children }: AppContextProviderType) => {
  const [isGameActive, setIsGameActive] = useState<boolean>(false);

  const AppContextValue: AppContextValueType = useMemo(
    () => ({
      isGameActive,
      setIsGameActive,
    }),
    [isGameActive]
  );

  return <AppContext.Provider value={AppContextValue}>{children}</AppContext.Provider>;
};

interface AppContextProviderType {
  children: ReactNode;
}

// src/context/ContextWrapper.tsx
import { ReactNode } from 'react';

import { AppContextProvider } from './AppContext';

const ContextWrapper = ({ children }: { children: ReactNode }) => (
  <AppContextProvider>
    {children}
  </AppContextProvider>
);

export default ContextWrapper;

export default function DashboardPage() {
  const { setIsGameActive } = useAppContext();
  useEffect(() => {
    setIsGameActive(false);
  }, [
    setIsGameActive,
  ]);
  ...
}

export default function LandingPage() {
  const { isGameActive } = useAppContext();

  return isGameActive ? <Game /> : <Dashboard />;
}

