#### ✅ 1. Basic syntax (TypeScript)

```tsx
const ref = useRef<Type>(initialValue);
```

👉 The key is typing the ref properly.

#### 🧩 2. Accessing DOM elements (most common)

##### ✅ Example: Input focus

```tsx
import { useRef } from "react";

export default function InputFocus() {
  const inputRef = useRef<HTMLInputElement>(null);

  const focusInput = () => {
    inputRef.current?.focus();
  };

  return (
    <div>
      <input ref={inputRef} />
      <button onClick={focusInput}>Focus</button>
    </div>
  );
}
```

###### ✅ Key points:

* `HTMLInputElement` = correct DOM type
* `?.` (optional chaining) because it may be `null`

#### 🧠 Common DOM types

| Element    | Type                |
| ---------- | ------------------- |
| `<input>`  | `HTMLInputElement`  |
| `<div>`    | `HTMLDivElement`    |
| `<button>` | `HTMLButtonElement` |
| `<form>`   | `HTMLFormElement`   |

#### ✅ 3. Scrolling example (DOM usage)

```tsx
const divRef = useRef<HTMLDivElement>(null);

const scrollToDiv = () => {
  divRef.current?.scrollIntoView({ behavior: "smooth" });
};

return (
  <>
    <button onClick={scrollToDiv}>Scroll</button>
    <div ref={divRef}>Target</div>
  </>
);
```

#### 🔄 4. Store mutable values (NO re-render)

👉 This is where `useRef` is underrated

##### ✅ Example: Previous value

```tsx
import { useRef, useEffect } from "react";

function Example({ count }: { count: number }) {
  const prevCount = useRef<number | null>(null);

  useEffect(() => {
    prevCount.current = count;
  }, [count]);

  return (
    <div>
      <p>Current: {count}</p>
      <p>Previous: {prevCount.current}</p>
    </div>
  );
}
```

✅ Why useRef?

* updating `prevCount.current` does **NOT re-render**

#### ⏱️ 5. Timer example (very common)

```tsx
import { useRef, useEffect } from "react";

export default function Timer() {
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    intervalRef.current = setInterval(() => {
      console.log("tick");
    }, 1000);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, []);

  return <div>Running...</div>;
}
```

✅ Why useRef here?

* Store interval ID without re-render

#### 🎯 6. Avoid re-creating values

```tsx
const idRef = useRef<number>(0);

const handleClick = () => {
  idRef.current += 1;
  console.log(idRef.current);
};
```

👉 This persists across renders without triggering UI updates

#### ⚡ 7. Imperative actions (advanced usage)

##### Example: Trigger child methods (React 19 — `ref` as a prop)

```tsx
type InputHandle = {
  focus: () => void;
};

function CustomInput({ ref }: { ref?: React.Ref<InputHandle> }) {
  const inputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current?.focus(),
  }));

  return <input ref={inputRef} />;
}
```

```tsx
const parentRef = useRef<InputHandle>(null);

<button onClick={() => parentRef.current?.focus()}>Focus</button>
<CustomInput ref={parentRef} />
```

✅ Used in design systems and reusable components. In older React, wrap with `forwardRef` instead of a `ref` prop.

